fn main() {
 use std::io::Read;
 let mut input=String::new(); std::io::stdin().read_to_string(&mut input).unwrap();
 match input.trim() {
"empty" => { println!("{}", sum_all(&[])); },
"mixed" => { println!("{}", sum_all(&[-4, 0, 10])); },
"negative" => { println!("{}", sum_all(&[-7, -2])); },
"bound" => { println!("{}", sum_all(&[i32::MAX, -1])); },
_ => panic!("unknown fixed case")
 }
}

